package com.siam.deviceinfo.receiver;import android.content.*;import android.os.*;public class ChargerReceiver extends BroadcastReceiver {public void onReceive(Context c,Intent i){if(Intent.ACTION_POWER_CONNECTED.equals(i.getAction()))android.util.Log.i("DeviceInfo","Power connected");else if(Intent.ACTION_POWER_DISCONNECTED.equals(i.getAction()))android.util.Log.i("DeviceInfo","Power disconnected");}}
